const getInvStep = $.Steps.Get_Investigation;
const data = (getInvStep && getInvStep.data) ? getInvStep.data : {};
const status = data.status || 'failed';
const conclusions = data.conclusions || [];
const title = data.title || '';
const fullResponse = data.full_response || {};
const currentPollCount = Number($.Variables.investigation_poll_count || 0);

let newState;
if (status === 'conclusive' || status === 'inconclusive') {
  newState = 'completed';
} else if (status === 'failed' || status === 'error') {
  newState = 'failed';
} else if (status === 'cancelled') {
  newState = 'cancelled';
} else {
  newState = 'running';
}

const newPollCount = currentPollCount + 1;

$.Helpers.setVariable('investigation_state', newState);
$.Helpers.setVariable('investigation_poll_count', newPollCount);
$.Helpers.setVariable('investigation_conclusions', JSON.stringify(conclusions));
$.Helpers.setVariable('investigation_title', title);
$.Helpers.setVariable('investigation_status_raw', status);
$.Helpers.setVariable('investigation_summary', JSON.stringify(fullResponse));

return { state: newState, poll_count: newPollCount };

Classify the probable root cause of this operational service degradation incident.

Monitor context:
- Monitor name: {{ Source.monitor.name }}
- Monitor ID: {{ Source.monitor.id }}
- Monitor state: {{ Source.monitor.overall_state }}
- Alert type: {{ Source.monitor.event.alert_type }}
- Host: {{ Source.monitor.event.host }}
- Tags: {{ Source.monitor.tags }}
- Alert title: {{ Source.monitor.event.title }}
- Alert text: {{ Source.monitor.event.text }}

Bits Investigation context:
- Investigation ID: {{ Variables.investigation_id }}
- Investigation state: {{ Variables.investigation_state }}
- Raw investigation status: {{ Variables.investigation_status_raw }}
- Investigation title: {{ Variables.investigation_title }}
- Investigation conclusions: {{ Variables.investigation_conclusions }}
- Investigation full response: {{ Variables.investigation_summary }}

Return only the structured classification defined by the agent instructions.

The allowed root causes are:
- POOL: PgBouncer saturation, exhausted server connections, or waiting clients.
- DISK: synthetic POC log volume or filesystem saturation.
- AUTOSCALE: storefront capacity pressure during the approved traffic-spike scenario, with insufficient replicas.
- ROLLBACK: storefront regression correlated with the approved demo-bad release or deployment version.
- MEMORY_PRESSURE: application VM usable memory is critically low and correlates with backend degradation while CPU, pool, disk, deployment, and replica evidence are not dominant.
- UNKNOWN: insufficient, conflicting, mixed, unrelated, or vulnerability evidence.

Do not choose or generate a remediation action.
Do not execute remediation.
Do not call external actions.
Do not modify infrastructure.
Vulnerability findings are out of scope for this workflow and must be UNKNOWN.
For MEMORY_PRESSURE, require correlated low usable memory and backend service impact; high memory usage alone is insufficient.
Prefer UNKNOWN when evidence is insufficient or conflicting.

const raw = $.Steps.Run_Agent.finalResponse;

let result;

try {
  if (typeof raw === "string") {
    const cleanedRaw = raw
      .trim()
      .replace(/^```(?:json)?\s*/i, "")
      .replace(/\s*```$/, "")
      .trim();

    result = JSON.parse(cleanedRaw);
  } else if (raw && typeof raw === "object") {
    result = raw;
  } else {
    throw new Error("Agent response is empty or unsupported");
  }

  const allowedRootCauses = ["POOL", "DISK", "AUTOSCALE", "ROLLBACK", "MEMORY_PRESSURE", "UNKNOWN"];
  const candidateRootCause = typeof result.root_cause === "string" ? result.root_cause.trim().toUpperCase() : "UNKNOWN";
  const rootCause = allowedRootCauses.includes(candidateRootCause) ? candidateRootCause : "UNKNOWN";
  const confidence = Number(result.confidence);
  const confidenceValid = Number.isFinite(confidence) && confidence >= 0 && confidence <= 1;
  const confidenceSufficient = confidenceValid && confidence >= 0.8;
  const safeValid = typeof result.safe_to_remediate === "boolean";
  const outputValid = allowedRootCauses.includes(candidateRootCause) && confidenceValid && safeValid;

  $.Helpers.setVariable("root_cause", rootCause);
  $.Helpers.setVariable("classification_confidence", confidenceValid ? confidence : 0);
  $.Helpers.setVariable("confidence_sufficient", confidenceSufficient ? "true" : "false");
  $.Helpers.setVariable("safe_to_remediate", safeValid && result.safe_to_remediate ? "true" : "false");
  $.Helpers.setVariable("classification_reason", typeof result.reason === "string" ? result.reason : "");

  // Format evidence arrays as readable Slack bullet lists
  const evidenceArr = Array.isArray(result.evidence) ? result.evidence : [];
  const conflictingArr = Array.isArray(result.conflicting_evidence) ? result.conflicting_evidence : [];
  const missingArr = Array.isArray(result.missing_evidence) ? result.missing_evidence : [];

  const formatBullets = (arr) => arr.length > 0
    ? arr.map(item => `• ${item}`).join('\n')
    : '• No specific evidence recorded';

  $.Helpers.setVariable("classification_evidence", formatBullets(evidenceArr));
  $.Helpers.setVariable("classification_conflicting_evidence", formatBullets(conflictingArr));
  $.Helpers.setVariable("classification_missing_evidence", formatBullets(missingArr));
  $.Helpers.setVariable("classifier_output_valid", outputValid ? "true" : "false");
  if (!outputValid) { $.Helpers.setVariable("workflow_result", "CLASSIFIER_INVALID_OUTPUT"); }

  return { root_cause: rootCause, confidence: confidenceValid ? confidence : 0, confidence_sufficient: confidenceSufficient, safe_to_remediate: safeValid ? result.safe_to_remediate : false, output_valid: outputValid };

} catch (error) {
  $.Helpers.setVariable("root_cause", "UNKNOWN");
  $.Helpers.setVariable("classification_confidence", 0);
  $.Helpers.setVariable("confidence_sufficient", "false");
  $.Helpers.setVariable("safe_to_remediate", "false");
  $.Helpers.setVariable("classification_reason", `Agent response could not be parsed: ${error.message}`);
  $.Helpers.setVariable("classification_evidence", "• No specific evidence recorded");
  $.Helpers.setVariable("classification_conflicting_evidence", "• No specific evidence recorded");
  $.Helpers.setVariable("classification_missing_evidence", "• Valid structured agent response");
  $.Helpers.setVariable("classifier_output_valid", "false");
  $.Helpers.setVariable("workflow_result", "CLASSIFIER_INVALID_OUTPUT");
  return { root_cause: "UNKNOWN", confidence: 0, confidence_sufficient: false, safe_to_remediate: false, output_valid: false };
}

const response = $.Steps.Get_Memory_Pre_Remediation_Status || {};
const body = response.body || {};
const state = body.demo_state || {};
const totalBytes = Number(state.memory_total_bytes);
const availableBytes = Number(state.memory_available_bytes);
const usableFraction = Number(state.memory_usable_fraction);
const baseline = state.memory_profile === 'baseline_16g' && Number.isFinite(totalBytes);
const pressureActive = state.memory_pressure_active === true;
const pressureObserved = Number.isFinite(usableFraction) && usableFraction < 0.15;
const noConflict = state.pool_hog_running === false && state.disk_fault_active === false && state.autoscale_spike_active === false && state.deployment_demo_active === false;
const applicationHealthy = state.docker_available === true && state.pgbouncer_ready === true && state.storefront_healthy === true && state.traefik_healthy === true;
const responseValid = Number(response.status || 0) === 200 && body.ok === true && body.environment === 'poc';
const passed = responseValid && baseline && pressureActive && pressureObserved && noConflict && applicationHealthy && $.Variables.root_cause === 'MEMORY_PRESSURE';
const reasons = [];
if (!responseValid) reasons.push('status_response_invalid');
if (!baseline) reasons.push('application_vm_not_at_16g_baseline');
if (!pressureActive) reasons.push('memory_pressure_not_active');
if (!pressureObserved) reasons.push('usable_memory_not_below_15_percent');
if (!noConflict) reasons.push('conflicting_scenario_active');
if (!applicationHealthy) reasons.push('application_dependency_not_healthy');
$.Helpers.setVariable('memory_policy_passed', passed ? 'true' : 'false');
$.Helpers.setVariable('memory_policy_reason', passed ? 'approved_policy_conditions_met' : reasons.join(','));
$.Helpers.setVariable('memory_total_before_gib', Number.isFinite(totalBytes) ? (totalBytes / 1073741824).toFixed(1) : 'unknown');
$.Helpers.setVariable('memory_available_before_gib', Number.isFinite(availableBytes) ? (availableBytes / 1073741824).toFixed(1) : 'unknown');
$.Helpers.setVariable('memory_usable_before_pct', Number.isFinite(usableFraction) ? (usableFraction * 100).toFixed(1) : 'unknown');
$.Helpers.setVariable('memory_target_profile', 'application_vm_memory_24g');
return { passed, reason: passed ? 'approved_policy_conditions_met' : reasons.join(','), total_bytes: totalBytes, usable_fraction: usableFraction };

const rootCause = String($.Variables.root_cause || '').toUpperCase();

const config = {
  POOL: {
    backend: 'AAP',
    response: $.Steps.Remediate_Pool_AAP,
    action: 'recover-pool',
    templateId: '18',
    templateName: 'Pool Remediation'
  },
  DISK: {
    backend: 'AAP',
    response: $.Steps.Remediate_Disk_AAP,
    action: 'recover-disk',
    templateId: '19',
    templateName: 'Disk Remediation'
  },
  AUTOSCALE: {
    backend: 'DEMO_CONTROL',
    response: $.Steps.Remediate_Autoscale_Demo,
    action: 'scale-storefront-to-2',
    templateId: '',
    templateName: ''
  },
  ROLLBACK: {
    backend: 'DEMO_CONTROL',
    response: $.Steps.Remediate_Rollback_Demo,
    action: 'rollback-storefront-stable',
    templateId: '',
    templateName: ''
  }
};

const selected = config[rootCause] || {};
const response = selected.response || {};
const body = response.body || {};
const httpStatus = Number(response.status || 0);

let accepted = false;
let jobId = '';
let rawState = '';

if (selected.backend === 'AAP') {
  jobId = body.id !== undefined && body.id !== null ? String(body.id) : '';
  rawState = String(body.status || 'pending');
  accepted = httpStatus === 201 && jobId !== '';
} else if (selected.backend === 'DEMO_CONTROL') {
  jobId = typeof body.job_id === 'string' ? body.job_id : '';
  rawState = String(body.state || '');
  accepted =
    httpStatus === 202 &&
    body.ok === true &&
    body.action === selected.action &&
    body.state === 'accepted' &&
    jobId !== '';
}

$.Helpers.setVariable('remediation_backend', selected.backend || 'UNKNOWN');
$.Helpers.setVariable('remediation_action', selected.action || 'none');
$.Helpers.setVariable('remediation_job_id', jobId);
$.Helpers.setVariable('remediation_status_raw', rawState);
$.Helpers.setVariable('remediation_state', accepted ? 'accepted' : 'failed');
$.Helpers.setVariable('aap_job_template_id', selected.templateId || '');
$.Helpers.setVariable('aap_job_template_name', selected.templateName || '');
$.Helpers.setVariable(
  'remediation_execution_detail',
  selected.backend === 'AAP'
    ? `${selected.templateName} (JT ${selected.templateId})`
    : `Demo Control API · ${selected.action}`
);
$.Helpers.setVariable(
  'remediation_failure_reason',
  accepted ? '' : 'Remediation backend did not return the expected launch response'
);

return {
  accepted,
  backend: selected.backend || 'UNKNOWN',
  http_status: httpStatus,
  job_id: jobId,
  raw_state: rawState
};

const backend = $.Variables.remediation_backend;
const expectedJobId = String($.Variables.remediation_job_id || '');

let response = {};
let valid = false;
let rawState = '';
let normalizedState = 'failed';
let failureReason = '';

if (backend === 'AAP') {
  response = $.Steps.Get_AAP_Remediation_Status || {};
  const body = response.body || {};
  const responseJobId =
    body.id !== undefined && body.id !== null ? String(body.id) : '';

  valid = Number(response.status || 0) === 200 && responseJobId === expectedJobId;
  rawState = String(body.status || '');

  if (['pending', 'waiting', 'running'].includes(rawState)) {
    normalizedState = 'running';
  } else if (rawState === 'successful') {
    normalizedState = 'succeeded';
  } else if (['failed', 'error', 'canceled'].includes(rawState)) {
    normalizedState = 'failed';
    failureReason = 'AAP terminal state: ' + rawState;
  } else {
    valid = false;
    failureReason = 'Unexpected AAP job state: ' + rawState;
  }
} else if (backend === 'DEMO_CONTROL') {
  response = $.Steps.Get_Demo_Remediation_Status || {};
  const body = response.body || {};
  const responseJobId = String(body.job_id || '');

  valid =
    Number(response.status || 0) === 200 &&
    body.ok === true &&
    responseJobId === expectedJobId;

  rawState = String(body.job_state || '');

  if (['accepted', 'running'].includes(rawState)) {
    normalizedState = 'running';
  } else if (rawState === 'succeeded') {
    normalizedState = 'succeeded';
  } else if (rawState === 'failed') {
    normalizedState = 'failed';
    failureReason = String(
      (body.job && body.job.error) ||
      body.error ||
      'Demo Control remediation job failed'
    );
  } else {
    valid = false;
    failureReason = 'Unexpected Demo Control job state: ' + rawState;
  }
}

const currentPollCount = Number($.Variables.remediation_poll_count || 0);
const nextPollCount = currentPollCount + 1;

if (!valid) {
  normalizedState = 'failed';
  if (!failureReason) {
    failureReason =
      'Remediation status response was invalid, unauthorized, unreachable, or did not match the launched job';
  }
}

const inProgress = normalizedState === 'running' && nextPollCount < 30;

let finalState = normalizedState;
if (normalizedState === 'running' && nextPollCount >= 30) {
  finalState = 'timeout';
  failureReason = 'Remediation job did not reach a terminal state within 300 seconds';
}

$.Helpers.setVariable('remediation_status_raw', rawState);
$.Helpers.setVariable('remediation_state', finalState);
$.Helpers.setVariable('remediation_poll_count', nextPollCount);
$.Helpers.setVariable('remediation_in_progress', inProgress ? 'true' : 'false');
if (failureReason) {
  $.Helpers.setVariable('remediation_failure_reason', failureReason);
}

return {
  valid,
  backend,
  raw_state: rawState,
  state: finalState,
  poll_count: nextPollCount,
  in_progress: inProgress,
  failure_reason: failureReason
};

const count = Number($.Variables.remediation_poll_count || 0);
// Normalize_Remediation_Status increments the count itself. This step only increments when status retrieval failed before normalization.
if ($.Variables.remediation_state === 'failed' && count === 0) {
  $.Helpers.setVariable('remediation_poll_count', 1);
  return 1;
}
return count;

const rootCause = String($.Variables.root_cause || 'UNKNOWN').toUpperCase();
let state = String($.Variables.remediation_state || 'failed');

const fallback = {
  POOL: {
    backend: 'AAP',
    action: 'recover-pool',
    templateId: '18',
    templateName: 'Pool Remediation',
    detail: 'Pool Remediation (JT 18)'
  },
  DISK: {
    backend: 'AAP',
    action: 'recover-disk',
    templateId: '19',
    templateName: 'Disk Remediation',
    detail: 'Disk Remediation (JT 19)'
  },
  AUTOSCALE: {
    backend: 'DEMO_CONTROL',
    action: 'scale-storefront-to-2',
    templateId: '',
    templateName: '',
    detail: 'Demo Control API · scale-storefront-to-2'
  },
  ROLLBACK: {
    backend: 'DEMO_CONTROL',
    action: 'rollback-storefront-stable',
    templateId: '',
    templateName: '',
    detail: 'Demo Control API · rollback-storefront-stable'
  },
  MEMORY_PRESSURE: {
    backend: 'MANUAL_PRISM',
    action: 'hot_add_memory',
    templateId: '',
    templateName: '',
    detail: 'Manual Nutanix Prism hot-add from 16 GiB to fixed 24 GiB profile'
  }
}[rootCause] || {};

if (state !== 'timeout') {
  state = 'failed';
}

const workflowResult =
  state === 'timeout' ? 'REMEDIATION_TIMEOUT' : 'REMEDIATION_FAILED';

$.Helpers.setVariable('workflow_result', workflowResult);
$.Helpers.setVariable('verification_status', 'skipped');
$.Helpers.setVariable('remediation_state', state);
$.Helpers.setVariable(
  'remediation_backend',
  $.Variables.remediation_backend || fallback.backend || 'UNKNOWN'
);
$.Helpers.setVariable(
  'remediation_action',
  $.Variables.remediation_action || fallback.action || 'none'
);
$.Helpers.setVariable(
  'aap_job_template_id',
  $.Variables.aap_job_template_id || fallback.templateId || ''
);
$.Helpers.setVariable(
  'aap_job_template_name',
  $.Variables.aap_job_template_name || fallback.templateName || ''
);
$.Helpers.setVariable(
  'remediation_execution_detail',
  $.Variables.remediation_execution_detail || fallback.detail || ''
);
$.Helpers.setVariable(
  'remediation_failure_reason',
  $.Variables.remediation_failure_reason ||
    'Remediation launch or execution did not complete successfully'
);
$.Helpers.setVariable('monitor_name', $.Source.monitor.name);
$.Helpers.setVariable('monitor_alert_url', $.Source.monitor.url);

return {
  workflow_result: workflowResult,
  remediation_state: state,
  remediation_backend: $.Variables.remediation_backend || fallback.backend || 'UNKNOWN',
  failure_reason:
    $.Variables.remediation_failure_reason ||
    'Remediation launch or execution did not complete successfully'
};

const statusResponse = $.Steps.Get_Verification_Status || {};
const statusBody = statusResponse.body || {};
const state = statusBody.demo_state || {};
const monitor = $.Steps.Verify_Composite_Monitor || {};
const monitorState = String(monitor.overall_state || '').toUpperCase();
const catalog = $.Steps.Verify_Storefront_Catalog || {};
const catalogStatus = Number(catalog.status || 0);
const classification = String($.Variables.root_cause || '').toUpperCase();
const currentPollCount = Number($.Variables.verification_poll_count || 0);
const nextPollCount = currentPollCount + 1;
const numeric = (value) => {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : null;
};

const controlPlaneHealthy =
  Number(statusResponse.status || 0) === 200 &&
  statusBody.ok === true &&
  statusBody.environment === 'poc' &&
  state.docker_available === true;
const monitorReadable = monitorState !== '';
const common = controlPlaneHealthy && monitorReadable && monitorState === 'OK';

let runtimeHealthy = false;
let reason = 'waiting_for_telemetry_and_runtime_state';
let verificationStatus = 'polling';

if (!controlPlaneHealthy) {
  verificationStatus = 'failed';
  reason = 'control_plane_api_unavailable';
} else if (!monitorReadable) {
  verificationStatus = 'failed';
  reason = 'datadog_monitor_status_unavailable';
} else if (common && classification === 'POOL') {
  runtimeHealthy =
    state.pgbouncer_ready === true &&
    state.pool_hog_running === false &&
    String(state.pool_size) === '5' &&
    String(state.max_db_connections) === '5' &&
    numeric(state.cl_waiting) === 0;
  reason = runtimeHealthy
    ? 'pool_queue_cleared_and_monitor_ok'
    : 'waiting_for_pool_runtime_state';
} else if (common && classification === 'DISK') {
  const usage = numeric(state.disk_usage_pct);
  runtimeHealthy =
    state.disk_fault_active === false &&
    (state.disk_mounted === false || (usage !== null && usage < 20));
  reason = runtimeHealthy
    ? 'synthetic_disk_fault_cleared_and_monitor_ok'
    : 'waiting_for_disk_runtime_state';
} else if (common && classification === 'AUTOSCALE') {
  runtimeHealthy =
    String(state.storefront_replicas) === '2' &&
    state.storefront_healthy === true &&
    state.traefik_healthy === true &&
    state.autoscale_spike_active === true &&
    state.autoscale_state === 'scaled_out';
  reason = runtimeHealthy
    ? 'two_healthy_replicas_and_monitor_ok'
    : 'waiting_for_storefront_scale_state';
} else if (common && classification === 'ROLLBACK') {
  runtimeHealthy =
    state.storefront_release_state === 'stable' &&
    state.deployment_demo_active === false &&
    String(state.storefront_replicas) === '1' &&
    state.storefront_healthy === true &&
    state.traefik_healthy === true &&
    catalogStatus === 200;
  reason = runtimeHealthy
    ? 'stable_release_catalog_and_monitor_recovered'
    : 'waiting_for_stable_release_or_catalog';
} else if (common && classification === 'MEMORY_PRESSURE') {
  const totalBytes = numeric(state.memory_total_bytes);
  const usableFraction = numeric(state.memory_usable_fraction);
  const minimumTargetBytes = 23 * 1024 * 1024 * 1024;
  runtimeHealthy =
    state.memory_pressure_active === true &&
    state.memory_profile === 'target_24g' &&
    totalBytes !== null &&
    totalBytes >= minimumTargetBytes &&
    usableFraction !== null &&
    usableFraction > 0.30 &&
    state.storefront_healthy === true &&
    state.traefik_healthy === true &&
    catalogStatus === 200;
  reason = runtimeHealthy
    ? '24g_memory_profile_usable_capacity_and_monitor_recovered'
    : 'waiting_for_memory_hot_add_and_service_recovery';
  $.Helpers.setVariable(
    'memory_total_after_gib',
    totalBytes !== null ? (totalBytes / 1073741824).toFixed(1) : 'unknown'
  );
  $.Helpers.setVariable(
    'memory_usable_after_pct',
    usableFraction !== null ? (usableFraction * 100).toFixed(1) : 'unknown'
  );
}

const passed = common && runtimeHealthy;
if (passed) {
  verificationStatus = 'passed';
}

$.Helpers.setVariable('monitor_state', monitorState);
$.Helpers.setVariable('verification_poll_count', nextPollCount);
$.Helpers.setVariable('monitor_name', monitor.name || $.Source.monitor.name);
$.Helpers.setVariable('monitor_alert_url', monitor.url || $.Source.monitor.url);
$.Helpers.setVariable('verification_status', verificationStatus);
$.Helpers.setVariable('verification_reason', reason);

return {
  passed,
  reason,
  monitor_state: monitorState,
  catalog_status: catalogStatus,
  poll_count: nextPollCount
};

const passed = $.Variables.verification_status === 'passed';
const workflowResult = passed ? 'REMEDIATION_SUCCEEDED' : 'VERIFICATION_FAILED';
const verificationStatus = passed ? 'passed' : 'failed';
$.Helpers.setVariable('workflow_result', workflowResult);
$.Helpers.setVariable('verification_status', verificationStatus);
if (passed && $.Variables.remediation_backend === 'MANUAL_PRISM') {
  $.Helpers.setVariable('remediation_state', 'telemetry_verified');
  $.Helpers.setVariable('remediation_status_raw', 'guest_memory_profile_verified');
}
if (!passed && $.Variables.verification_reason !== 'control_plane_api_unavailable' && $.Variables.verification_reason !== 'datadog_monitor_status_unavailable') {
  $.Helpers.setVariable('verification_reason', 'verification_window_exhausted');
}
return { workflow_result: workflowResult, verification_status: verificationStatus };
